cat > /tmp/m2ts_debug.c <<'EOF'
#include <gpac/mpegts.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
static void dump(GF_M2TS_Demuxer *ts, const char *tag) {
    fprintf(stderr, "-- %s pck=%u --\n", tag, ts->pck_number);
    for (u32 i=0;i<GF_M2TS_MAX_STREAMS;i++) {
        GF_M2TS_ES *es = ts->ess[i];
        if (es) fprintf(stderr, " ess[%u]=%p es.pid=%u flags=0x%x st=0x%x prog=%p pcr=%u streams=%u\n", i, (void*)es, es->pid, es->flags, es->stream_type, (void*)es->program, es->program?es->program->pcr_pid:99999, es->program?gf_list_count(es->program->streams):0);
    }
}
int main(int argc, char **argv) {
    if (argc<2) return 2;
    FILE *f=fopen(argv[1], "rb"); if(!f) return 3;
    fseek(f,0,SEEK_END); long sz=ftell(f); fseek(f,0,SEEK_SET);
    unsigned char *buf=malloc(sz); fread(buf,1,sz,f); fclose(f);
    GF_M2TS_Demuxer *ts=gf_m2ts_demux_new();
    dump(ts,"init");
    for (long off=0; off<sz; off+=188) {
        u32 n = (sz-off>=188)?188:(sz-off);
        fprintf(stderr,"PROCESS off=%ld pid=%u\n", off, ((buf[off+1]&0x1f)<<8)|buf[off+2]);
        gf_m2ts_process_data(ts, buf+off, n);
        dump(ts,"after");
    }
    fprintf(stderr,"DEMUX_DEL\n");
    gf_m2ts_demux_del(ts);
    fprintf(stderr,"DONE\n");
    free(buf);
    return 0;
}
